import { defineComponent } from 'vue';
import { inversifyContainer } from '../../inversify/container';
import { bootstrapErrorModel } from '../../models/error-model';

export default defineComponent({
    name: 'ErrorView',
    components: {},
    props: {

    },
    data() {
        return {};
    },
    computed: {
        errorMessage() {
            const defaultError = inversifyContainer.errorStrings.default;
            if (bootstrapErrorModel.resumeErrorResultCode) {
                return inversifyContainer.errorStrings[bootstrapErrorModel.resumeErrorResultCode.ResultCode] ?? `${defaultError} ${bootstrapErrorModel.resumeErrorResultCode.ResultCode}`;
            }
            return defaultError;
        },
        closeMessage() {
            return inversifyContainer.errorStrings.close ?? 'close';
        }
    },
    mounted(): void { },
    methods: {
        onCloseClicked(): void {
            // TODO: confirm what we want to do here instead of closing the game
            // inversifyContainer.frameConnection.goToHome();
        }
    }
});
